import { useEffect, useRef, useState } from "react";
import type { ReactNode } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

type Worker = { id: string; label: string; username: string; status: string; buyerId: string | null };
type Product = "ADMIN_BROADCAST" | "USERBOT_PROMO" | "LEGACY_BUNDLE";
type Buyer = { id: string; name: string; telegramId?: string; planBroadcast: boolean; planUserBroadcast?: boolean; planComment: boolean; legacyBundle?: boolean; broadcastActive: boolean; userBroadcastActive?: boolean; commentActive: boolean; commentAccountConnected: boolean; userbotAccountStatus?: "DISCONNECTED" | "CONNECTING" | "CONNECTED" | "RECONNECT_REQUIRED"; userbotAccountIssue?: string; workerId: string | null; userBroadcastEditingBy?: "ADMIN" | "BUYER" };
type Package = { packageId?: string; id?: string; service: Product; name: string; price: number; durationDays: number; maxGroups: number; enabled?: boolean };
type PackageDraft = Omit<Package, "price" | "durationDays" | "maxGroups"> & { price: string; durationDays: string; maxGroups: string };
type CommerceOrder = { id: string; orderId: string; buyer: string; plan: Product | "BUNDLE"; durationDays: number; maxGroups: number; amount: number; status: "PENDING" | "PAID" | "FAILED" | "EXPIRED"; createdAt: string; paidAt?: string };
type CommerceWithdrawal = { id: string; grossAmount: number; fee: number; netAmount: number; walletType: "DANA" | "GoPay" | "OVO" | "ShopeePay" | "LinkAja"; walletNumber: string; walletOwner: string; status: "REQUESTED" | "PAID"; createdAt: string; paidAt?: string };
type PayoutProfile = { walletType: "DANA" | "GoPay" | "OVO" | "ShopeePay" | "LinkAja"; walletNumber: string; walletOwner: string; updatedAt: string };
type Commerce = { today: number; week: number; month: number; paidCount: number; pendingBalance: number; availableBalance: number; requestedBalance: number; canRequestWithdrawal: boolean; orders: CommerceOrder[]; withdrawals: CommerceWithdrawal[] };
type LpmTarget = { id: string; buyerId: string; workerId?: string; executor?: "ADMIN" | "BUYER"; username: string; status: "CONNECTING" | "PENDING_APPROVAL" | "READY" | "UNAVAILABLE" | "REMOVING" | "REMOVED"; desired: boolean; note?: string };
type CommentDivision = { id: string; name: string; keywords: string[]; blacklist: string[]; wording: string };
type CommentConfig = { buyerId: string; bases: string[]; divisions: CommentDivision[]; mode: "APPROVAL" | "AUTO"; updatedAt: string; updatedBy: "ADMIN" | "BUYER"; editingBy?: "ADMIN" | "BUYER"; editingUntil?: string };
type BroadcastMode = "TEXT" | "FORWARD";
type ForwardSource = { channel: string; messageId: number; showSource: boolean };
type BroadcastConfig = { buyerId: string; executor?: "ADMIN" | "BUYER"; wording: string; mode: BroadcastMode; forward?: ForwardSource; groups: string[]; intervalMinutes: number };
type AdminOverview = { buyers: Buyer[]; workers: Worker[]; workerSessions?: string[]; broadcasts: BroadcastConfig[]; lpmTargets: LpmTarget[]; comments: CommentConfig[]; packages: Package[]; commerce: Commerce };
type BroadcastDraft = { mode: BroadcastMode; wording: string; forwardLink: string; showForwardSource: boolean; groups: string; intervalMinutes: string };
type Dashboard = { onboarding?: boolean; buyer: Buyer | null; broadcastQuota?: number | null; userBroadcastQuota?: number | null; worker: Worker | null; broadcast: BroadcastConfig | null; userBroadcast: BroadcastConfig | null; lpmTargets: LpmTarget[]; userLpmTargets: LpmTarget[]; commentTargets: { id: string; base: string; discussion?: string; status: string }[]; comment: Omit<CommentConfig, "buyerId"> | null; activity: { kind: string; status: string; label: string; link?: string; at: string }[] };
declare global { interface Window { Telegram?: { WebApp?: { initData: string; initDataUnsafe?: { start_param?: string }; ready: () => void; expand: () => void; openLink?: (url: string) => void } } } }
const telegramApp = window.Telegram?.WebApp;
telegramApp?.ready(); telegramApp?.expand();
const buyerHeaders = { ...(telegramApp?.initData ? { "x-telegram-init-data": telegramApp.initData } : { "x-buyer-id": "0" }), "content-type": "application/json" };
const api = async <T,>(url: string, options?: RequestInit): Promise<T> => { const headers = new Headers(options?.headers); if (telegramApp?.initData) headers.set("x-telegram-init-data", telegramApp.initData); else if (!headers.has("x-buyer-id")) headers.set("x-buyer-id", "0"); const res = await fetch(url, { ...options, headers }); const data = await res.json(); if (!res.ok) throw new Error(data.reason ?? data.error); return data; };

function Toggle({ on, disabled, onClick, ariaLabel }: { on: boolean; disabled?: boolean; onClick: () => void; ariaLabel: string }) { return <button aria-label={ariaLabel} className={`toggle ${on ? "on" : ""}`} disabled={disabled} onClick={onClick}><i /></button>; }
function Tag({ children, kind = "soft" }: { children: ReactNode; kind?: string }) { return <span className={`tag ${kind}`}>{children}</span>; }

type ProductIconName = "broadcast" | "comment";

function ProductIcon({ name }: { name: ProductIconName | "sales" }) {
  const common = { fill: "none", stroke: "currentColor", strokeWidth: 1.7, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  return name === "broadcast"
    ? <svg viewBox="0 0 24 24" aria-hidden="true"><path {...common} d="m5 10.2 11.6-5.1v13.8L5 13.8v-3.6Z" /><path {...common} d="M8.3 15.2 9.6 19h3.1l-.8-4.9M19 8.2c1 .8 1.5 1.9 1.5 3.1s-.5 2.3-1.5 3.1" /></svg>
    : name === "comment" ? <svg viewBox="0 0 24 24" aria-hidden="true"><path {...common} d="M4.5 6.7c0-1.2 1-2.2 2.2-2.2h10.6c1.2 0 2.2 1 2.2 2.2v6.6c0 1.2-1 2.2-2.2 2.2h-6.4L7 19v-3.5H6.7c-1.2 0-2.2-1-2.2-2.2V6.7Z" /><path {...common} d="M8 10h.01M12 10h.01M16 10h.01" strokeWidth="2.5" /></svg>
      : <svg viewBox="0 0 24 24" aria-hidden="true"><path {...common} d="M5 3.8h10.7l3.3 3.3v13.1H5V3.8Z" /><path {...common} d="M15.7 3.8v3.4h3.4M8 11h8M8 14.5h8M8 18h4.5" /></svg>;
}

function activityLabel(kind: string) { return kind === "broadcast" ? "Sebar" : "Komen"; }
function productLabel(product: Product | "BUNDLE") { return product === "ADMIN_BROADCAST" ? "Auto Sebar" : product === "USERBOT_PROMO" ? "Userbot Promosi" : "Paket lama"; }
function packageLabel(item: Package) { return `${item.durationDays} hari · ${item.maxGroups} LPM`; }
function rupiah(value: number) { return "Rp" + new Intl.NumberFormat("id-ID").format(value); }
function dateTime(value?: string) { return value ? new Intl.DateTimeFormat("id-ID", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Jakarta" }).format(new Date(value)) : "—"; }
function orderStatus(status: CommerceOrder["status"]) { return ({ PAID: "Lunas", PENDING: "Menunggu", FAILED: "Gagal", EXPIRED: "Lewat waktu" } as const)[status]; }
function withdrawalStatus(status: CommerceWithdrawal["status"]) { return status === "PAID" ? "Selesai" : "Diajukan"; }
function returnedPaymentOrder() { const value = telegramApp?.initDataUnsafe?.start_param ?? new URLSearchParams(window.location.search).get("tgWebAppStartParam") ?? new URLSearchParams(window.location.search).get("payment") ?? ""; return /^paid_(payment_[a-z0-9]+)$/i.exec(value)?.[1] ?? (/^payment_[a-z0-9]+$/i.test(value) ? value : ""); }
function lpmStatus(status: LpmTarget["status"]) { return ({ CONNECTING: "Menyiapkan", PENDING_APPROVAL: "Menunggu persetujuan", READY: "Grup siap", UNAVAILABLE: "Tidak bisa", REMOVING: "Menghapus", REMOVED: "Dihapus" } as const)[status]; }
function commentTargetStatus(status: string) { return ({ READY: "Siap", PENDING_APPROVAL: "Menunggu persetujuan", MUTED: "Tidak bisa", UNAVAILABLE: "Tidak bisa", CHECKING: "Menyiapkan" } as Record<string, string>)[status] ?? "Menyiapkan"; }
function activityStatus(status: string) { return ({ queued: "Antre", sent: "Terkirim", failed: "Gagal", deleted: "Dihapus", delete_failed: "Gagal hapus" } as Record<string, string>)[status] ?? (status ? status[0].toUpperCase() + status.slice(1) : status); }
type ServiceState = "Aktif" | "Siap" | "Menyiapkan" | "Belum ada akses";
function StatusChip({ state }: { state: ServiceState }) { return <Tag kind={`service-state ${state === "Aktif" ? "active" : state === "Siap" ? "ready" : state === "Menyiapkan" ? "preparing" : "no-access"}`}>{state}</Tag>; }
function forwardLink(source?: ForwardSource) { return source ? `https://t.me/${source.channel}/${source.messageId}` : ""; }
function ListEditor({ value, onChange, placeholder, disabled }: { value: string; onChange: (next: string) => void; placeholder: string; disabled?: boolean }) {
  const rows = value.split("\n");
  const setRow = (index: number, next: string) => onChange(rows.map((row, i) => i === index ? next : row).join("\n"));
  const removeRow = (index: number) => onChange(rows.filter((_, i) => i !== index).join("\n"));
  return <div className="list-editor">{rows.map((row, index) => <div className="list-editor-row" key={index}><input disabled={disabled} value={row} onChange={(event) => setRow(index, event.target.value)} placeholder={placeholder} />{!disabled && rows.length > 1 && <button type="button" className="list-editor-remove" onClick={() => removeRow(index)}>×</button>}</div>)}{!disabled && <button type="button" className="list-editor-add" onClick={() => onChange([...rows, ""].join("\n"))}>+ Tambah</button>}</div>;
}
function BroadcastContentFields({ value, onChange }: { value: Pick<BroadcastDraft, "mode" | "wording" | "forwardLink" | "showForwardSource">; onChange: (next: Partial<BroadcastDraft>) => void }) { return <div className="broadcast-content"><div className="broadcast-mode" role="group" aria-label="Jenis kiriman"><button className={value.mode === "TEXT" ? "chosen" : ""} type="button" onClick={() => onChange({ mode: "TEXT" })}>Tulis wording</button><button className={value.mode === "FORWARD" ? "chosen" : ""} type="button" onClick={() => onChange({ mode: "FORWARD" })}>Forward post</button></div>{value.mode === "TEXT" ? <label>Wording<textarea value={value.wording} onChange={(event) => onChange({ wording: event.target.value })} placeholder="Tulis wording promosi…" /></label> : <><label>Link bubble chat wording<small>Post wording ke channel publik lo, buka post-nya, salin tautan bubble chat, lalu tempel di sini.</small><input value={value.forwardLink} onChange={(event) => onChange({ forwardLink: event.target.value })} placeholder="https://t.me/namachannel/123" /></label><label className="forward-source"><input type="checkbox" checked={value.showForwardSource} onChange={(event) => onChange({ showForwardSource: event.target.checked })} /> Tampilkan sumber forward</label></>}</div>; }

function SubscriptionClosed() {
  return <main className="shell welcome checkout">
    <header><div className="eyebrow">PAKET PROMOSI</div><h1>Langganan sementara ditutup.</h1><p>Aktivasi layanan saat ini dibantu langsung oleh admin.</p></header>
    <section className="choice-panel subscription-closed"><span className="icon-tile comment-icon"><ProductIcon name="comment" /></span><div><b>Butuh akses layanan?</b><span>Hubungi admin untuk pengaktifan Auto Sebar dan Auto Komen MF.</span></div><a href="https://t.me/Kertaaji" target="_blank" rel="noreferrer">@Kertaaji</a></section>
  </main>;
}

function BuyerApp() {
  const [data, setData] = useState<Dashboard | null>(null); const [error, setError] = useState(""); const [busy, setBusy] = useState(""); const [broadcastSetupOpen, setBroadcastSetupOpen] = useState(false); const [broadcastForm, setBroadcastForm] = useState<BroadcastDraft>({ mode: "TEXT", wording: "", forwardLink: "", showForwardSource: false, groups: "", intervalMinutes: "15" }); const [userBroadcastSetupOpen, setUserBroadcastSetupOpen] = useState(false); const [userBroadcastEditing, setUserBroadcastEditing] = useState(false); const [userBroadcastForm, setUserBroadcastForm] = useState<BroadcastDraft>({ mode: "TEXT", wording: "", forwardLink: "", showForwardSource: false, groups: "", intervalMinutes: "15" }); const [commentLoginOpen, setCommentLoginOpen] = useState(false); const [commentLoginStep, setCommentLoginStep] = useState<"PHONE" | "CODE" | "PASSWORD">("PHONE"); const [commentPhone, setCommentPhone] = useState(""); const [commentCode, setCommentCode] = useState(""); const [commentPassword, setCommentPassword] = useState(""); const [commentSetupOpen, setCommentSetupOpen] = useState(false); const [commentEditing, setCommentEditing] = useState(false); const [commentForm, setCommentForm] = useState<CommentSetupDraft>({ bases: "", mode: "APPROVAL", divisions: [newDivision()], activeDivision: 0 });
  const load = async () => { try { setData(await api<Dashboard>("/api/buyer/dashboard", { headers: buyerHeaders })); } catch (e) { setError((e as Error).message); } };
  useEffect(() => { void load(); const timer = window.setInterval(() => { if (document.visibilityState === "visible") void load(); }, 3_000); return () => window.clearInterval(timer); }, []);
  const change = async (feature: "BROADCAST" | "USERBOT_BROADCAST" | "COMMENT", active: boolean) => { setBusy(feature); setError(""); try { await api("/api/buyer/toggle", { method: "POST", headers: buyerHeaders, body: JSON.stringify({ feature, active }) }); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const sendCommentCode = async () => { setBusy("CONNECT"); setError(""); try { await api("/api/buyer/comment-account/send-code", { method: "POST", headers: buyerHeaders, body: JSON.stringify({ phone: commentPhone }) }); setCommentLoginStep("CODE"); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const verifyCommentCode = async () => { setBusy("CONNECT"); setError(""); try { const result = await api<{ next: "PASSWORD" | "DONE" }>("/api/buyer/comment-account/verify-code", { method: "POST", headers: buyerHeaders, body: JSON.stringify({ code: commentCode }) }); if (result.next === "PASSWORD") setCommentLoginStep("PASSWORD"); else { setCommentLoginOpen(false); await load(); } } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const verifyCommentPassword = async () => { setBusy("CONNECT"); setError(""); try { await api("/api/buyer/comment-account/verify-password", { method: "POST", headers: buyerHeaders, body: JSON.stringify({ password: commentPassword }) }); setCommentLoginOpen(false); setCommentPassword(""); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  if (!data) return <main className="shell loading">{error ? <div className="notice error">{error}</div> : "Memuat layanan…"}</main>;
  if (!data.buyer || (!data.buyer.planBroadcast && !data.buyer.planUserBroadcast && !data.buyer.planComment)) return <SubscriptionClosed />;
  const { buyer, worker, broadcast, userBroadcast, comment } = data;
  const readyLpmCount = data.lpmTargets.filter((item) => item.desired && item.status === "READY").length;
  const readyUserLpmCount = data.userLpmTargets.filter((item) => item.desired && item.status === "READY").length;
  const readyCommentTargetCount = data.commentTargets.filter((item) => item.status === "READY").length;
  const broadcastState: ServiceState = !buyer.planBroadcast ? "Belum ada akses" : buyer.broadcastActive ? "Aktif" : broadcast && readyLpmCount ? "Siap" : "Menyiapkan";
  const userBroadcastState: ServiceState = !buyer.planUserBroadcast ? "Belum ada akses" : buyer.userBroadcastActive ? "Aktif" : buyer.commentAccountConnected && userBroadcast && readyUserLpmCount ? "Siap" : "Menyiapkan";
  const commentState: ServiceState = !buyer.planComment ? "Belum ada akses" : buyer.commentActive ? "Aktif" : buyer.commentAccountConnected && comment && readyCommentTargetCount ? "Siap" : "Menyiapkan";
  const openBroadcastSetup = () => { setError(""); setBroadcastForm({ mode: broadcast?.mode ?? "TEXT", wording: broadcast?.wording ?? "", forwardLink: forwardLink(broadcast?.forward), showForwardSource: broadcast?.forward?.showSource ?? false, groups: broadcast?.groups.join("\n") ?? "", intervalMinutes: String(broadcast?.intervalMinutes ?? 15) }); setBroadcastSetupOpen(true); };
  const saveBroadcastSetup = async () => { setBusy("BROADCAST_SETUP"); setError(""); try { await api("/api/buyer/broadcast-setup", { method: "PUT", headers: buyerHeaders, body: JSON.stringify({ ...broadcastForm, groups: broadcastForm.groups.split("\n").map((item) => item.trim()).filter(Boolean) }) }); setBroadcastSetupOpen(false); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const openUserBroadcastSetup = async () => { setBusy("USERBOT_BROADCAST_EDIT"); setError(""); try { await api("/api/buyer/userbot-broadcast/edit", { method: "POST", headers: buyerHeaders, body: "{}" }); setUserBroadcastForm({ mode: userBroadcast?.mode ?? "TEXT", wording: userBroadcast?.wording ?? "", forwardLink: forwardLink(userBroadcast?.forward), showForwardSource: userBroadcast?.forward?.showSource ?? false, groups: userBroadcast?.groups.join("\n") ?? "", intervalMinutes: String(userBroadcast?.intervalMinutes ?? 15) }); setUserBroadcastEditing(true); setUserBroadcastSetupOpen(true); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const cancelUserBroadcastSetup = async () => { setBusy("USERBOT_BROADCAST_EDIT"); try { await api("/api/buyer/userbot-broadcast/cancel", { method: "POST", headers: buyerHeaders, body: "{}" }); } finally { setUserBroadcastEditing(false); setUserBroadcastSetupOpen(false); setBusy(""); await load(); } };
  const saveUserBroadcastSetup = async () => { setBusy("USERBOT_BROADCAST_SETUP"); setError(""); try { await api("/api/buyer/userbot-broadcast-setup", { method: "PUT", headers: buyerHeaders, body: JSON.stringify({ ...userBroadcastForm, groups: userBroadcastForm.groups.split("\n").map((item) => item.trim()).filter(Boolean) }) }); setUserBroadcastEditing(false); setUserBroadcastSetupOpen(false); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const setupDraft = (source: Dashboard["comment"]) => ({ bases: source?.bases.join("\n") ?? "", mode: source?.mode ?? "APPROVAL" as "APPROVAL" | "AUTO", divisions: source?.divisions.length ? source.divisions.map(divisionDraft) : [newDivision()], activeDivision: 0 });
  const openCommentSetup = () => { setCommentForm(setupDraft(data.comment)); setCommentSetupOpen(true); };
  const beginCommentEdit = async () => { setBusy("COMMENT_EDIT"); setError(""); try { const result = await api<{ config: CommentConfig }>("/api/buyer/comment-config/edit", { method: "POST", headers: buyerHeaders, body: "{}" }); setCommentForm(setupDraft(result.config)); setCommentEditing(true); setCommentSetupOpen(true); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  const cancelCommentEdit = async () => { setBusy("COMMENT_EDIT"); try { await api("/api/buyer/comment-config/cancel", { method: "POST", headers: buyerHeaders, body: "{}" }); } finally { setBusy(""); setCommentEditing(false); setCommentSetupOpen(false); await load(); } };
  const saveCommentSetup = async () => { setBusy("COMMENT_SAVE"); setError(""); try { await api("/api/buyer/comment-config", { method: "PUT", headers: buyerHeaders, body: JSON.stringify({ bases: commentForm.bases, mode: commentForm.mode, divisions: commentForm.divisions.map(({ id, name, keywords, blacklist, wording }) => ({ id, name, keywords: keywords.split("\n").map((item) => item.trim()).filter(Boolean), blacklist: blacklist.split("\n").map((item) => item.trim()).filter(Boolean), wording })) }) }); setCommentEditing(false); setCommentSetupOpen(false); await load(); } catch (e) { setError((e as Error).message); } finally { setBusy(""); } };
  return <main className="shell">
    <header><div className="eyebrow">PUSAT PROMOSI</div><h1>Halo, {buyer.name}.</h1><p>Kelola layanan lo dari sini.</p></header>
    {error && <div className="notice error">{error}</div>}
    <section className="service-card broadcast-card"><div className="service-top"><div><span className="icon-tile broadcast-icon"><ProductIcon name="broadcast" /></span><div><div className="label">AUTO SEBAR</div><div className="service-title-line"><h2>Auto Sebar</h2><StatusChip state={broadcastState} /></div></div></div><Toggle ariaLabel="Auto Sebar" on={buyer.broadcastActive} disabled={busy === "BROADCAST" || !buyer.planBroadcast || !broadcast || (!buyer.broadcastActive && !readyLpmCount)} onClick={() => void change("BROADCAST", !buyer.broadcastActive)} /></div>
      {buyer.planBroadcast && broadcast ? <><div className="signal"><b>{broadcastState}</b><span>{readyLpmCount}/{broadcast.groups.length} grup siap · {broadcast.intervalMinutes}m</span></div><div className="excerpt">{broadcast.mode === "FORWARD" ? `Forward dari @${broadcast.forward?.channel ?? "channel"}` : broadcast.wording}</div><div className="lpm-target-list">{data.lpmTargets.map((target) => <div className={`lpm-target ${target.status.toLowerCase()}`} key={target.id}><b>@{target.username}</b><span>{lpmStatus(target.status)}</span></div>)}</div><button className="small-button" onClick={openBroadcastSetup}>Ubah setup</button></> : buyer.planBroadcast ? <button className="outline" onClick={openBroadcastSetup}>Atur Auto Sebar</button> : null}
      {broadcastSetupOpen && <section className="buyer-broadcast-setup"><div className="section-title"><span>SETUP AUTO SEBAR</span><button onClick={() => setBroadcastSetupOpen(false)}>Batal</button></div><BroadcastContentFields value={broadcastForm} onChange={(next) => setBroadcastForm((item) => ({ ...item, ...next }))} /><label>Grup LPM{data.broadcastQuota ? <small>maks. {data.broadcastQuota}</small> : null}<ListEditor value={broadcastForm.groups} onChange={(next) => setBroadcastForm((item) => ({ ...item, groups: next }))} placeholder="username_grup" /></label><label>Jeda (menit)<input inputMode="numeric" value={broadcastForm.intervalMinutes} onChange={(e) => setBroadcastForm((item) => ({ ...item, intervalMinutes: e.target.value }))} /></label><button className="save" disabled={busy === "BROADCAST_SETUP"} onClick={() => void saveBroadcastSetup()}>{busy === "BROADCAST_SETUP" ? "Menyimpan…" : "Simpan setup"}</button></section>}
    </section>
    {(buyer.planUserBroadcast || buyer.planComment) && <section className="service-card comment-card userbot-card"><div className="service-top"><div><span className="icon-tile comment-icon"><ProductIcon name="comment" /></span><div><div className="label">USERBOT PROMOSI</div><div className="service-title-line"><h2>{buyer.commentAccountConnected ? "Akun tersambung" : "Hubungkan akun"}</h2><StatusChip state={buyer.commentAccountConnected ? "Siap" : "Menyiapkan"} /></div></div></div></div>
      {!buyer.commentAccountConnected && <><button className="outline" disabled={busy === "CONNECT"} onClick={() => { setCommentLoginOpen(true); setCommentLoginStep("PHONE"); }}>{buyer.userbotAccountStatus === "RECONNECT_REQUIRED" ? "Hubungkan ulang" : "Hubungkan akun"}</button>{buyer.userbotAccountStatus === "RECONNECT_REQUIRED" && <div className="setup-lock">{buyer.userbotAccountIssue || "Sesi akun sudah tidak aktif. Hubungkan ulang untuk lanjut."}</div>}</>}
      {commentLoginOpen && <section className="buyer-broadcast-setup comment-login"><div className="section-title"><span>HUBUNGKAN AKUN</span><button onClick={() => setCommentLoginOpen(false)}>Batal</button></div>{commentLoginStep === "PHONE" && <><label>Nomor Telegram<input value={commentPhone} onChange={(event) => setCommentPhone(event.target.value)} placeholder="+628…" /></label><button className="save orange-save" disabled={busy === "CONNECT"} onClick={() => void sendCommentCode()}>{busy === "CONNECT" ? "Mengirim…" : "Kirim kode"}</button></>}{commentLoginStep === "CODE" && <><label>Kode Telegram<input inputMode="numeric" value={commentCode} onChange={(event) => setCommentCode(event.target.value)} /></label><button className="save orange-save" disabled={busy === "CONNECT"} onClick={() => void verifyCommentCode()}>{busy === "CONNECT" ? "Memeriksa…" : "Lanjut"}</button></>}{commentLoginStep === "PASSWORD" && <><label>Password 2FA<input type="password" value={commentPassword} onChange={(event) => setCommentPassword(event.target.value)} /></label><button className="save orange-save" disabled={busy === "CONNECT"} onClick={() => void verifyCommentPassword()}>{busy === "CONNECT" ? "Memeriksa…" : "Hubungkan akun"}</button></>}</section>}
      <div className="userbot-module"><div className="userbot-module-head"><div className="service-title-line"><b>Auto Jaseb</b><StatusChip state={userBroadcastState} /></div><Toggle ariaLabel="Auto Jaseb" on={Boolean(buyer.userBroadcastActive)} disabled={busy === "USERBOT_BROADCAST" || !buyer.planUserBroadcast || !userBroadcast || (!buyer.userBroadcastActive && !readyUserLpmCount)} onClick={() => void change("USERBOT_BROADCAST", !buyer.userBroadcastActive)} /></div>{userBroadcast && <><div className="signal"><b>{userBroadcastState}</b><span>{readyUserLpmCount}/{userBroadcast.groups.length} grup siap · {userBroadcast.intervalMinutes}m</span></div><div className="excerpt">{userBroadcast.mode === "FORWARD" ? `Forward dari @${userBroadcast.forward?.channel ?? "channel"}` : userBroadcast.wording}</div><div className="lpm-target-list">{data.userLpmTargets.map((target) => <div className={`lpm-target ${target.status.toLowerCase()}`} key={target.id}><b>@{target.username}</b><span>{lpmStatus(target.status)}</span></div>)}</div></>}{buyer.planUserBroadcast && buyer.commentAccountConnected && <button className="small-button" disabled={busy === "USERBOT_BROADCAST_EDIT"} onClick={() => void openUserBroadcastSetup()}>{userBroadcast ? "Ubah Auto Jaseb" : "Atur Auto Jaseb"}</button>}{userBroadcastSetupOpen && <section className="buyer-broadcast-setup"><div className="section-title"><span>SETUP AUTO JASEB</span><button disabled={busy === "USERBOT_BROADCAST_EDIT"} onClick={() => void cancelUserBroadcastSetup()}>Batal</button></div><BroadcastContentFields value={userBroadcastForm} onChange={(next) => setUserBroadcastForm((item) => ({ ...item, ...next }))} /><label>Grup LPM{data.userBroadcastQuota ? <small>maks. {data.userBroadcastQuota}</small> : null}<ListEditor value={userBroadcastForm.groups} onChange={(next) => setUserBroadcastForm((item) => ({ ...item, groups: next }))} placeholder="username_grup" /></label><label>Jeda (menit)<input inputMode="numeric" value={userBroadcastForm.intervalMinutes} onChange={(event) => setUserBroadcastForm((item) => ({ ...item, intervalMinutes: event.target.value }))} /></label><button className="save orange-save" disabled={!userBroadcastEditing || busy === "USERBOT_BROADCAST_SETUP"} onClick={() => void saveUserBroadcastSetup()}>{busy === "USERBOT_BROADCAST_SETUP" ? "Menyimpan…" : "Simpan setup"}</button></section>}</div>
      <div className="userbot-module"><div className="userbot-module-head"><div className="service-title-line"><b>Auto Komen MF</b><StatusChip state={commentState} /></div><Toggle ariaLabel="Auto Komen" on={buyer.commentActive} disabled={busy === "COMMENT" || !buyer.planComment || !buyer.commentAccountConnected || !comment || (!buyer.commentActive && !readyCommentTargetCount)} onClick={() => void change("COMMENT", !buyer.commentActive)} /></div>{buyer.planComment && buyer.commentAccountConnected && <>{comment && <><div className="compact-grid"><div><span>BASE</span><b>{comment.bases.length}</b></div><div><span>KEYWORD</span><b>{comment.divisions.reduce((total, item) => total + item.keywords.length, 0)}</b></div><div><span>MODE</span><b>{comment.mode === "AUTO" ? "Otomatis" : "Approval"}</b></div></div><div className="setup-meta">Terakhir diatur {comment.updatedBy === "ADMIN" ? "admin" : "buyer"}.</div>{data.commentTargets.length ? <div className="lpm-target-list">{data.commentTargets.map((target) => <div className={`lpm-target ${target.status.toLowerCase()}`} key={target.id}><b>@{target.base}</b><span>{commentTargetStatus(target.status)}</span></div>)}</div> : null}</>}{comment?.editingBy === "ADMIN" && <div className="setup-lock">Setup sedang diatur admin.</div>}{!commentSetupOpen ? <button className="small-button" disabled={comment?.editingBy === "ADMIN" || busy === "COMMENT_EDIT"} onClick={() => void beginCommentEdit()}>{busy === "COMMENT_EDIT" ? "Membuka…" : "Atur setup"}</button> : <section className="buyer-broadcast-setup comment-setup"><div className="section-title"><span>SETUP AUTO KOMEN</span><button disabled={busy === "COMMENT_EDIT"} onClick={() => void cancelCommentEdit()}>Batal</button></div><CommentSetupFields value={commentForm} onChange={setCommentForm} disabled={!commentEditing} /><button className="save orange-save" disabled={!commentEditing || busy === "COMMENT_SAVE"} onClick={() => void saveCommentSetup()}>{busy === "COMMENT_SAVE" ? "Menyimpan…" : "Simpan setup"}</button></section>}</>}</div>
    </section>}
    <section className="activity"><div className="section-title"><span>AKTIVITAS</span><b>30 hari</b></div>{data.activity.length ? data.activity.map((item, index) => <div className="activity-row" key={index}><i className={item.kind.toLowerCase()} /><div><b>{item.link ? <a href={item.link} target="_blank" rel="noreferrer">{item.label}</a> : item.label}</b><span>{item.kind} · {new Date(item.at).toLocaleString("id-ID")}</span></div><Tag>{activityStatus(item.status)}</Tag></div>) : <div className="empty">Belum ada aktivitas.</div>}</section>
  </main>;
}

type DivisionDraft = { id: string; name: string; keywords: string; blacklist: string; wording: string };
const newDivision = (): DivisionDraft => ({ id: `division_${crypto.randomUUID().slice(0, 8)}`, name: "", keywords: "", blacklist: "", wording: "" });
const divisionDraft = (item?: CommentDivision): DivisionDraft => item ? { ...item, keywords: item.keywords.join("\n"), blacklist: item.blacklist.join("\n") } : newDivision();
type CommentSetupDraft = { bases: string; mode: "APPROVAL" | "AUTO"; divisions: DivisionDraft[]; activeDivision: number };
function CommentSetupFields({ value, onChange, disabled }: { value: CommentSetupDraft; onChange: (next: CommentSetupDraft) => void; disabled?: boolean }) {
  const division = value.divisions[value.activeDivision] ?? newDivision();
  const setDivision = (key: keyof Omit<DivisionDraft, "id">, next: string) => onChange({ ...value, divisions: value.divisions.map((item, index) => index === value.activeDivision ? { ...item, [key]: next } : item) });
  const add = () => onChange({ ...value, divisions: [...value.divisions, newDivision()], activeDivision: value.divisions.length });
  const remove = () => value.divisions.length > 1 && onChange({ ...value, divisions: value.divisions.filter((_, index) => index !== value.activeDivision), activeDivision: Math.max(0, value.activeDivision - 1) });
  return <div className={`comment-setup-fields${disabled ? " read-only" : ""}`}><label>Base<ListEditor disabled={disabled} value={value.bases} onChange={(next) => onChange({ ...value, bases: next })} placeholder="username_base" /></label><label>Metode<select disabled={disabled} value={value.mode} onChange={(event) => onChange({ ...value, mode: event.target.value as "APPROVAL" | "AUTO" })}><option value="APPROVAL">Approval</option><option value="AUTO">Otomatis</option></select></label><div className="division-editor"><div className="section-title"><span>DIVISI</span>{!disabled && <button onClick={add}>+ Divisi</button>}</div><div className="division-tabs">{value.divisions.map((item, index) => <button disabled={disabled} key={item.id} className={value.activeDivision === index ? "chosen" : ""} onClick={() => onChange({ ...value, activeDivision: index })}>{item.name || `Divisi ${index + 1}`}</button>)}</div><label>Divisi<input disabled={disabled} value={division.name} onChange={(event) => setDivision("name", event.target.value)} placeholder="Netflix" /></label><label>Keyword<textarea disabled={disabled} value={division.keywords} onChange={(event) => setDivision("keywords", event.target.value)} placeholder={"netflix\nnetflix prem\nnetflix 1d"} /></label><label>Blacklist Keyword OOT<textarea disabled={disabled} value={division.blacklist} onChange={(event) => setDivision("blacklist", event.target.value)} placeholder={"template\nsharing\nopen jasa"} /></label><label>Wording<textarea disabled={disabled} value={division.wording} onChange={(event) => setDivision("wording", event.target.value)} placeholder="Isi wording" /></label>{value.divisions.length > 1 && !disabled && <button className="quiet-button remove-division" onClick={remove}>Hapus divisi ini</button>}</div></div>;
}

function WorkerPage({ onBack }: { onBack: () => void }) {
  const [overview, setOverview] = useState<AdminOverview | null>(null); const [selected, setSelected] = useState(""); const [message, setMessage] = useState(""); const [adding, setAdding] = useState(false); const [newWorker, setNewWorker] = useState({ label: "" }); const [step, setStep] = useState<"PHONE" | "CODE" | "PASSWORD" | "DONE">("PHONE"); const [phone, setPhone] = useState(""); const [code, setCode] = useState(""); const [password, setPassword] = useState(""); const [busy, setBusy] = useState(false);
  const load = async () => { try { const next = await api<AdminOverview>("/api/admin/overview"); setOverview(next); setSelected((current) => current || next.workers[0]?.id || ""); } catch (error) { setMessage((error as Error).message); } };
  useEffect(() => { void load(); }, []);
  const worker = overview?.workers.find((item) => item.id === selected); const connected = Boolean(worker && overview?.workerSessions?.includes(worker.id));
  const addWorker = async () => { setBusy(true); setMessage(""); try { const result = await api<{ worker: Worker }>("/api/admin/workers", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(newWorker) }); setSelected(result.worker.id); setAdding(false); setNewWorker({ label: "" }); setStep("PHONE"); await load(); } catch (error) { setMessage((error as Error).message); } finally { setBusy(false); } };
  const sendCode = async () => { if (!worker) return; setBusy(true); setMessage(""); try { await api(`/api/admin/workers/${worker.id}/login/send-code`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ phone }) }); setStep("CODE"); } catch (error) { setMessage((error as Error).message); } finally { setBusy(false); } };
  const verifyCode = async () => { if (!worker) return; setBusy(true); setMessage(""); try { const result = await api<{ next: "PASSWORD" | "DONE"; username?: string }>(`/api/admin/workers/${worker.id}/login/verify-code`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ code }) }); if (result.next === "PASSWORD") setStep("PASSWORD"); else { setStep("DONE"); setMessage(`@${result.username} tersambung.`); await load(); } } catch (error) { setMessage((error as Error).message); } finally { setBusy(false); } };
  const verifyPassword = async () => { if (!worker) return; setBusy(true); setMessage(""); try { const result = await api<{ username: string }>(`/api/admin/workers/${worker.id}/login/verify-password`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ password }) }); setStep("DONE"); setMessage(`@${result.username} tersambung.`); setPassword(""); await load(); } catch (error) { setMessage((error as Error).message); } finally { setBusy(false); } };
  const remove = async () => { if (!worker || !window.confirm(`Hapus @${worker.username}?`)) return; setBusy(true); try { await api(`/api/admin/workers/${worker.id}`, { method: "DELETE" }); setSelected(""); setStep("PHONE"); await load(); } catch (error) { setMessage((error as Error).message); } finally { setBusy(false); } };
  if (!overview) return <main className="shell loading">Membuka akun worker…</main>;
  return <main className="shell admin worker-page"><header><button className="back-link" onClick={onBack}>← Panel admin</button><div className="eyebrow">AKUN WORKER</div><h1>Akun worker.</h1></header>{message && <div className="notice">{message}</div>}<section className="customer-chooser"><div className="section-title"><span>AKUN</span><button onClick={() => setAdding((value) => !value)}>+ Tambah</button></div>{adding && <div className="worker-add"><label>Nama akun<input value={newWorker.label} onChange={(event) => setNewWorker((old) => ({ ...old, label: event.target.value }))} /></label><button className="save" disabled={busy} onClick={() => void addWorker()}>Simpan akun</button></div>}<div className="buyer-picker">{overview.workers.map((item) => <button className={selected === item.id ? "chosen" : ""} key={item.id} onClick={() => { setSelected(item.id); setStep("PHONE"); setMessage(""); }}><b>{item.username ? `@${item.username}` : item.label}</b><span>{overview.workerSessions?.includes(item.id) ? "tersambung" : "belum terhubung"}</span></button>)}</div></section>{worker && <section className="customer-service service-broadcast"><div className="customer-service-head"><div><span className="icon-tile broadcast-icon"><ProductIcon name="broadcast" /></span><div className="label">{worker.username ? `@${worker.username}` : worker.label}</div></div><Tag>{connected ? "Tersambung" : "Belum terhubung"}</Tag></div>{!connected && <div className="worker-login">{step === "PHONE" && <><label>Nomor Telegram<input value={phone} onChange={(event) => setPhone(event.target.value)} placeholder="+628…" /></label><button className="save" disabled={busy} onClick={() => void sendCode()}>{busy ? "Mengirim…" : "Kirim kode"}</button></>}{step === "CODE" && <><label>Kode Telegram<input inputMode="numeric" value={code} onChange={(event) => setCode(event.target.value)} /></label><button className="save" disabled={busy} onClick={() => void verifyCode()}>{busy ? "Memeriksa…" : "Lanjut"}</button></>}{step === "PASSWORD" && <><label>Password 2FA<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} /></label><button className="save" disabled={busy} onClick={() => void verifyPassword()}>{busy ? "Memeriksa…" : "Hubungkan akun"}</button></>}</div>}<button className="quiet-button remove-worker" disabled={busy} onClick={() => void remove()}>Hapus akun worker</button></section>}</main>;
}

function CustomerPage({ onBack }: { onBack: () => void }) {
  const [overview, setOverview] = useState<AdminOverview | null>(null); const [selected, setSelected] = useState(""); const [message, setMessage] = useState(""); const [saving, setSaving] = useState(""); const [commentEditing, setCommentEditing] = useState(false); const [broadcastEditing, setBroadcastEditing] = useState(false); const [userBroadcastEditing, setUserBroadcastEditing] = useState(false); const [buyerSearch, setBuyerSearch] = useState("");
  const [broadcast, setBroadcast] = useState({ enabled: false, workerId: "", mode: "TEXT" as BroadcastMode, wording: "", forwardLink: "", showForwardSource: false, groups: "", intervalMinutes: "15" });
  const [userBroadcast, setUserBroadcast] = useState<BroadcastDraft>({ mode: "TEXT", wording: "", forwardLink: "", showForwardSource: false, groups: "", intervalMinutes: "15" });
  const [comment, setComment] = useState({ enabled: false, bases: "", mode: "APPROVAL" as "APPROVAL" | "AUTO", divisions: [newDivision()], activeDivision: 0 });
  const load = async () => { try { const next = await api<AdminOverview>("/api/admin/overview"); setOverview(next); setSelected((current) => current || next.buyers[0]?.id || ""); } catch (error) { setMessage((error as Error).message); } };
  useEffect(() => { void load(); const timer = window.setInterval(() => { if (!commentEditing && !broadcastEditing && !userBroadcastEditing && document.visibilityState === "visible") void load(); }, 3_000); return () => window.clearInterval(timer); }, [commentEditing, broadcastEditing, userBroadcastEditing]);
  const buyer = overview?.buyers.find((item) => item.id === selected);
  useEffect(() => {
    if (!buyer || !overview || commentEditing || broadcastEditing || userBroadcastEditing) return;
    const currentBroadcast = overview.broadcasts.find((item) => item.buyerId === buyer.id && item.executor !== "BUYER");
    const currentUserBroadcast = overview.broadcasts.find((item) => item.buyerId === buyer.id && item.executor === "BUYER");
    const currentComment = overview.comments.find((item) => item.buyerId === buyer.id);
    setBroadcast({ enabled: buyer.planBroadcast, workerId: buyer.workerId ?? "", mode: currentBroadcast?.mode ?? "TEXT", wording: currentBroadcast?.wording ?? "", forwardLink: forwardLink(currentBroadcast?.forward), showForwardSource: currentBroadcast?.forward?.showSource ?? false, groups: currentBroadcast?.groups.join("\n") ?? "", intervalMinutes: String(currentBroadcast?.intervalMinutes ?? 15) });
    setUserBroadcast({ mode: currentUserBroadcast?.mode ?? "TEXT", wording: currentUserBroadcast?.wording ?? "", forwardLink: forwardLink(currentUserBroadcast?.forward), showForwardSource: currentUserBroadcast?.forward?.showSource ?? false, groups: currentUserBroadcast?.groups.join("\n") ?? "", intervalMinutes: String(currentUserBroadcast?.intervalMinutes ?? 15) });
    setComment({ enabled: buyer.planComment, bases: currentComment?.bases.join("\n") ?? "", mode: currentComment?.mode ?? "APPROVAL", divisions: currentComment?.divisions.length ? currentComment.divisions.map(divisionDraft) : [newDivision()], activeDivision: 0 });
  }, [buyer?.id, overview, commentEditing, broadcastEditing, userBroadcastEditing]);
  const saveBroadcast = async () => { if (!buyer) return; setSaving("broadcast"); setMessage(""); try { await api(`/api/admin/buyers/${buyer.id}/broadcast-config`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...broadcast, groups: broadcast.groups.split("\n").map((item) => item.trim()).filter(Boolean) }) }); setMessage("Auto Sebar disimpan."); setBroadcastEditing(false); await load(); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const beginBroadcastEdit = async () => { if (!buyer) return; setSaving("broadcast-lock"); setMessage(""); try { await api(`/api/admin/buyers/${buyer.id}/broadcast-config/edit`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); setBroadcastEditing(true); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const cancelBroadcastEdit = async () => { if (!buyer) return; setSaving("broadcast-lock"); try { await api(`/api/admin/buyers/${buyer.id}/broadcast-config/cancel`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); setBroadcastEditing(false); await load(); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const beginUserBroadcastEdit = async () => { if (!buyer) return; setSaving("user-broadcast-lock"); setMessage(""); try { await api(`/api/admin/buyers/${buyer.id}/userbot-broadcast-config/edit`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); setUserBroadcastEditing(true); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const cancelUserBroadcastEdit = async () => { if (!buyer) return; setSaving("user-broadcast-lock"); try { await api(`/api/admin/buyers/${buyer.id}/userbot-broadcast-config/cancel`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); setUserBroadcastEditing(false); await load(); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const saveUserBroadcast = async () => { if (!buyer) return; setSaving("user-broadcast"); setMessage(""); try { await api(`/api/admin/buyers/${buyer.id}/userbot-broadcast-config`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...userBroadcast, groups: userBroadcast.groups.split("\n").map((item) => item.trim()).filter(Boolean) }) }); setMessage("Auto Jaseb buyer disimpan."); setUserBroadcastEditing(false); await load(); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const beginCommentEdit = async () => { if (!buyer) return; setSaving("comment-lock"); setMessage(""); try { const result = await api<{ config: CommentConfig }>(`/api/admin/buyers/${buyer.id}/comment-config/edit`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); const config = result.config; setComment((old) => ({ ...old, bases: config.bases.join("\n"), mode: config.mode, divisions: config.divisions.length ? config.divisions.map(divisionDraft) : [newDivision()], activeDivision: 0 })); setCommentEditing(true); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const cancelCommentEdit = async () => { if (!buyer) return; setSaving("comment-lock"); try { await api(`/api/admin/buyers/${buyer.id}/comment-config/cancel`, { method: "POST", headers: { "content-type": "application/json" }, body: "{}" }); setCommentEditing(false); await load(); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const saveComment = async () => { if (!buyer) return; setSaving("comment"); setMessage(""); try { await api(`/api/admin/buyers/${buyer.id}/comment-config`, { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ enabled: comment.enabled, bases: comment.bases, mode: comment.mode, divisions: comment.divisions.map(({ id, name, keywords, blacklist, wording }) => ({ id, name, keywords: keywords.split("\n").map((item) => item.trim()).filter(Boolean), blacklist: blacklist.split("\n").map((item) => item.trim()).filter(Boolean), wording })) }) }); setMessage("Auto Komen MF disimpan."); setCommentEditing(false); await load(); } catch (error) { setMessage((error as Error).message); } finally { setSaving(""); } };
  const updateDivision = (key: keyof Omit<DivisionDraft, "id">, value: string) => setComment((old) => ({ ...old, divisions: old.divisions.map((item, index) => index === old.activeDivision ? { ...item, [key]: value } : item) }));
  const addDivision = () => setComment((old) => ({ ...old, divisions: [...old.divisions, newDivision()], activeDivision: old.divisions.length }));
  const removeDivision = () => setComment((old) => old.divisions.length === 1 ? old : { ...old, divisions: old.divisions.filter((_, index) => index !== old.activeDivision), activeDivision: Math.max(0, old.activeDivision - 1) });
  if (!overview) return <main className="shell loading">Membuka pelanggan…</main>;
  const division = comment.divisions[comment.activeDivision]; const buyerTargets = overview.lpmTargets.filter((item) => item.buyerId === selected && item.workerId === buyer?.workerId);
  const buyerQuery = buyerSearch.trim().toLowerCase(); const visibleBuyers = buyerQuery ? overview.buyers.filter((item) => item.name.toLowerCase().includes(buyerQuery) || (item.telegramId ?? "").toLowerCase().includes(buyerQuery)) : overview.buyers;
  return <main className="shell admin customer-page"><header><button className="back-link" onClick={onBack}>← Panel admin</button><div className="eyebrow">PELANGGAN</div><h1>Pelanggan.</h1></header>{message && <div className="notice">{message}</div>}
    <section className="customer-chooser"><div className="section-title"><span>PELANGGAN</span><small>Terdaftar otomatis saat buka Mini App</small></div><input className="buyer-search" value={buyerSearch} onChange={(event) => setBuyerSearch(event.target.value)} placeholder="Cari nama atau ID Telegram…" />{buyerQuery && <div className="setup-meta">{visibleBuyers.length} dari {overview.buyers.length} pelanggan</div>}<div className="buyer-picker">{visibleBuyers.length ? visibleBuyers.map((item) => <button className={selected === item.id ? "chosen" : ""} key={item.id} onClick={() => setSelected(item.id)}><b>{item.name}</b><span>{item.planBroadcast || item.planComment ? "aktif" : "baru"}</span></button>) : <div className="empty">Gak ada pelanggan yang cocok.</div>}</div></section>
    {buyer ? <><section className="customer-service service-broadcast"><div className="customer-service-head"><div><span className="icon-tile broadcast-icon"><ProductIcon name="broadcast" /></span><div className="label">AUTO SEBAR</div></div><label className="service-switch"><input type="checkbox" checked={broadcast.enabled} onChange={(event) => { const next = event.target.checked; setBroadcast((old) => ({ ...old, enabled: next })); if (!next && broadcastEditing) void cancelBroadcastEdit(); }} /> Aktif</label></div>{broadcast.enabled ? <div className="customer-form">{!broadcastEditing && <><div className="setup-meta">{buyer.workerId ? "Sudah diatur." : "Belum diatur. Bisa kasih akses dulu, setup nyusul — buyer bisa atur sendiri atau hubungi admin."}</div><div className="editor-actions">{!buyer.workerId && <button className="save" disabled={saving === "broadcast"} onClick={() => void saveBroadcast()}>{saving === "broadcast" ? "Menyimpan…" : "Simpan akses"}</button>}<button className="small-button" disabled={saving === "broadcast-lock"} onClick={() => void beginBroadcastEdit()}>{saving === "broadcast-lock" ? "Membuka…" : "Atur setup"}</button></div></>}{broadcastEditing && <><label>Akun<select value={broadcast.workerId} onChange={(event) => setBroadcast((old) => ({ ...old, workerId: event.target.value }))}><option value="">Pilih akun</option>{overview.workers.filter((item) => item.username && (!item.buyerId || item.buyerId === buyer.id)).map((item) => <option value={item.id} key={item.id}>{item.label} · @{item.username}</option>)}</select></label><BroadcastContentFields value={broadcast} onChange={(next) => setBroadcast((old) => ({ ...old, ...next }))} /><label>Grup LPM<ListEditor value={broadcast.groups} onChange={(next) => setBroadcast((old) => ({ ...old, groups: next }))} placeholder="username_grup" /></label><label>Jeda (menit)<input inputMode="numeric" value={broadcast.intervalMinutes} onChange={(event) => setBroadcast((old) => ({ ...old, intervalMinutes: event.target.value }))} /></label>{buyerTargets.length ? <div className="lpm-target-list">{buyerTargets.map((item) => <div className={`lpm-target ${item.status.toLowerCase()}`} key={item.id}><b>@{item.username}</b><span>{lpmStatus(item.status)}</span></div>)}</div> : null}<div className="editor-actions"><button className="quiet-button" disabled={saving === "broadcast"} onClick={() => void cancelBroadcastEdit()}>Batal</button><button className="save" disabled={saving === "broadcast"} onClick={() => void saveBroadcast()}>{saving === "broadcast" ? "Menyimpan…" : "Simpan setup"}</button></div></>}</div> : <button className="save" disabled={saving === "broadcast"} onClick={() => void saveBroadcast()}>{saving === "broadcast" ? "Menyimpan…" : "Simpan akses"}</button>}</section>
      <section className="customer-service service-comment"><div className="customer-service-head"><div><span className="icon-tile comment-icon"><ProductIcon name="comment" /></span><div className="label">USERBOT PROMOSI · AUTO KOMEN</div></div><label className="service-switch orange"><input type="checkbox" checked={comment.enabled} onChange={(event) => setComment((old) => ({ ...old, enabled: event.target.checked }))} /> Aktif</label></div>{comment.enabled ? <div className="customer-form">{!commentEditing && <><div className="setup-meta">{overview.comments.find((item) => item.buyerId === buyer.id)?.editingBy === "BUYER" ? "Setup sedang diatur buyer." : overview.comments.find((item) => item.buyerId === buyer.id)?.bases.length ? "Sudah diatur." : "Belum diatur."}</div><div className="editor-actions">{!overview.comments.find((item) => item.buyerId === buyer.id)?.bases.length && <button className="save orange-save" disabled={saving === "comment"} onClick={() => void saveComment()}>{saving === "comment" ? "Menyimpan…" : "Simpan akses"}</button>}<button className="small-button" disabled={saving === "comment-lock" || overview.comments.find((item) => item.buyerId === buyer.id)?.editingBy === "BUYER"} onClick={() => void beginCommentEdit()}>{saving === "comment-lock" ? "Membuka…" : "Atur setup"}</button></div></>}{commentEditing && <><CommentSetupFields value={comment} onChange={(next) => setComment((old) => ({ ...old, ...next }))} /><div className="editor-actions"><button className="quiet-button" disabled={saving === "comment"} onClick={() => void cancelCommentEdit()}>Batal</button><button className="save orange-save" disabled={saving === "comment"} onClick={() => void saveComment()}>{saving === "comment" ? "Menyimpan…" : "Simpan setup"}</button></div></>}</div> : <button className="save orange-save" disabled={saving === "comment"} onClick={() => void saveComment()}>{saving === "comment" ? "Menyimpan…" : "Simpan akses"}</button>}</section>
      {buyer.planUserBroadcast && <section className="customer-service service-comment"><div className="customer-service-head"><div><span className="icon-tile broadcast-icon"><ProductIcon name="broadcast" /></span><div className="label">USERBOT PROMOSI · AUTO JASEB</div></div><Tag>{buyer.commentAccountConnected ? "Akun terhubung" : "Menunggu akun"}</Tag></div>{!userBroadcastEditing ? <div className="customer-form"><div className="setup-meta">{overview.broadcasts.some((item) => item.buyerId === buyer.id && item.executor === "BUYER") ? "Sudah diatur." : "Belum diatur."}</div><button className="small-button" disabled={saving === "user-broadcast-lock" || buyer.userBroadcastEditingBy === "BUYER"} onClick={() => void beginUserBroadcastEdit()}>{saving === "user-broadcast-lock" ? "Membuka…" : "Atur setup"}</button></div> : <div className="customer-form"><BroadcastContentFields value={userBroadcast} onChange={(next) => setUserBroadcast((old) => ({ ...old, ...next }))} /><label>Grup LPM<ListEditor value={userBroadcast.groups} onChange={(next) => setUserBroadcast((old) => ({ ...old, groups: next }))} placeholder="username_grup" /></label><label>Jeda (menit)<input inputMode="numeric" value={userBroadcast.intervalMinutes} onChange={(event) => setUserBroadcast((old) => ({ ...old, intervalMinutes: event.target.value }))} /></label><div className="editor-actions"><button className="quiet-button" disabled={saving === "user-broadcast"} onClick={() => void cancelUserBroadcastEdit()}>Batal</button><button className="save orange-save" disabled={saving === "user-broadcast"} onClick={() => void saveUserBroadcast()}>{saving === "user-broadcast" ? "Menyimpan…" : "Simpan setup"}</button></div></div>}</section>}</> : <div className="empty">Tambahkan pelanggan untuk mulai setup.</div>}
  </main>;
}

function CommercePage({ onBack }: { onBack: () => void }) {
  const [commerce, setCommerce] = useState<Commerce | null>(null); const [profile, setProfile] = useState<PayoutProfile | null>(null); const [error, setError] = useState(""); const [requesting, setRequesting] = useState(false); const [savingProfile, setSavingProfile] = useState(false); const [editingProfile, setEditingProfile] = useState(false); const [notice, setNotice] = useState(""); const [wallet, setWallet] = useState({ type: "DANA", number: "", owner: "" }); const profileLoaded = useRef(false);
  const load = async () => { try { const [overview, payout] = await Promise.all([api<AdminOverview>("/api/admin/overview"), api<{ profile: PayoutProfile | null }>("/api/admin/payout-profile")]); setCommerce(overview.commerce); setProfile(payout.profile); if (!profileLoaded.current) { if (payout.profile) { setWallet({ type: payout.profile.walletType, number: payout.profile.walletNumber, owner: payout.profile.walletOwner }); } setEditingProfile(!payout.profile); profileLoaded.current = true; } } catch (e) { setError((e as Error).message); } };
  useEffect(() => { void load(); const timer = window.setInterval(() => void load(), 30_000); return () => window.clearInterval(timer); }, []);
  const savePayoutProfile = async () => { if (!wallet.number.trim() || !wallet.owner.trim()) { setError("Lengkapi tujuan e-wallet dulu."); return; } setSavingProfile(true); setError(""); setNotice(""); try { const result = await api<{ profile: PayoutProfile }>("/api/admin/payout-profile", { method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify({ walletType: wallet.type, walletNumber: wallet.number, walletOwner: wallet.owner }) }); setProfile(result.profile); setWallet({ type: result.profile.walletType, number: result.profile.walletNumber, owner: result.profile.walletOwner }); setEditingProfile(false); setNotice("Tujuan penarikan disimpan."); } catch (e) { setError((e as Error).message); } finally { setSavingProfile(false); } };
  const requestWithdrawal = async () => { if (!profile) { setError("Atur tujuan e-wallet dulu."); setEditingProfile(true); return; } setRequesting(true); setError(""); setNotice(""); try { const result = await api<{ commerce: Commerce }>("/api/admin/withdrawals", { method: "POST" }); setCommerce(result.commerce); setNotice("Permintaan penarikan sudah dikirim."); } catch (e) { setError((e as Error).message); } finally { setRequesting(false); } };
  if (!commerce) return <main className="shell admin commerce-page loading">{error ? <div className="notice error">{error}</div> : "Memuat penjualan…"}</main>;
  return <main className="shell admin commerce-page"><header><button className="back-link" onClick={onBack}>← Panel admin</button><div className="eyebrow">PENJUALAN</div><h1>Catatan masuk.</h1><p>Hanya pembayaran lunas yang masuk ke pendapatan.</p></header>
    {error && <div className="notice error">{error}</div>}{notice && <div className="notice">{notice}</div>}
    <section className="revenue-strip"><div><span>HARI INI</span><b>{rupiah(commerce.today)}</b></div><div><span>MINGGU INI</span><b>{rupiah(commerce.week)}</b></div><div><span>BULAN INI</span><b>{rupiah(commerce.month)}</b></div></section>
    <section className="withdraw-card"><div className="ledger-head"><div><div className="label">TARIK SALDO</div><h2>Saldo Pakasir</h2></div><span className="withdraw-fee">Fee Rp5.000</span></div><div className="balance-lines"><span>Belum bisa ditarik<b>{rupiah(commerce.pendingBalance)}</b></span><span>Siap ditarik<b>{rupiah(commerce.availableBalance)}</b></span>{commerce.requestedBalance > 0 && <span>Sedang diajukan<b>{rupiah(commerce.requestedBalance)}</b></span>}</div><div className="withdraw-destination"><div className="withdraw-destination-head"><b>Tujuan penarikan</b>{profile && !editingProfile && <button onClick={() => setEditingProfile(true)}>Ubah</button>}</div>{editingProfile ? <><label>E-wallet tujuan<select value={wallet.type} onChange={(event) => setWallet((item) => ({ ...item, type: event.target.value }))}><option value="DANA">DANA</option><option value="GoPay">GoPay</option><option value="OVO">OVO</option><option value="ShopeePay">ShopeePay</option><option value="LinkAja">LinkAja</option></select></label><label>Nomor e-wallet<input inputMode="numeric" value={wallet.number} onChange={(event) => setWallet((item) => ({ ...item, number: event.target.value }))} placeholder="08xxxxxxxxxx" /></label><label>Nama pemilik<input value={wallet.owner} onChange={(event) => setWallet((item) => ({ ...item, owner: event.target.value }))} placeholder="Sesuai akun e-wallet" /></label><button className="small-button" disabled={savingProfile} onClick={() => void savePayoutProfile()}>{savingProfile ? "Menyimpan…" : "Simpan tujuan"}</button></> : <div className="payout-profile"><b>{profile?.walletType}</b><span>{profile?.walletNumber}</span><small>a.n. {profile?.walletOwner}</small></div>}</div><button className="withdraw-button" disabled={!profile || !commerce.canRequestWithdrawal || requesting} onClick={() => void requestWithdrawal()}>{requesting ? "Mengirim…" : !profile ? "Atur tujuan e-wallet dulu" : commerce.canRequestWithdrawal ? `Tarik ${rupiah(commerce.availableBalance)}` : commerce.availableBalance < 30_000 ? "Minimum tarik Rp30.000" : "Tersedia mulai 12.30 WIB"}</button></section>
      <section className="order-ledger"><div className="ledger-head"><div><div className="label">RIWAYAT ORDER</div><h2>Transaksi terbaru</h2></div><Tag>{commerce.paidCount} lunas</Tag></div>{commerce.orders.length ? <div className="order-list">{commerce.orders.map((order) => <article className="order-row" key={order.id}><div className="order-main"><div className="order-title"><b>{order.buyer}</b><Tag kind={order.status.toLowerCase()}>{orderStatus(order.status)}</Tag></div><span>{productLabel(order.plan)} · {order.durationDays} hari · {order.maxGroups} LPM</span><small>{order.status === "PAID" ? `Lunas ${dateTime(order.paidAt)}` : `Dibuat ${dateTime(order.createdAt)}`} · {order.orderId}</small></div><strong>{rupiah(order.amount)}</strong></article>)}</div> : <div className="order-empty">Belum ada order.</div>}</section>
    {commerce.withdrawals.length > 0 && <section className="withdraw-history"><div className="ledger-head"><div><div className="label">RIWAYAT PENARIKAN</div><h2>Pengajuan terakhir</h2></div></div>{commerce.withdrawals.map((item) => <article className="withdraw-row" key={item.id}><div><b>{rupiah(item.netAmount)}</b><span>Tarik {rupiah(item.grossAmount)} · fee {rupiah(item.fee)}</span><small>{item.walletType} · {item.walletNumber} · a.n. {item.walletOwner}</small><small>{item.status === "PAID" ? `Dikirim ${dateTime(item.paidAt)}` : `Diajukan ${dateTime(item.createdAt)}`}</small></div><Tag kind={item.status === "PAID" ? "paid" : "pending"}>{withdrawalStatus(item.status)}</Tag></article>)}</section>}
  </main>;
}

function AdminApp() {
  const [overview, setOverview] = useState<AdminOverview | null>(null);
  const [panelOpen, setPanelOpen] = useState(false); const [customerPage, setCustomerPage] = useState(false); const [workerPage, setWorkerPage] = useState(false); const [commercePage, setCommercePage] = useState(false); const [settingUp, setSettingUp] = useState(false); const [addingBuyer, setAddingBuyer] = useState(false); const [addingWorker, setAddingWorker] = useState(false); const [newBuyer, setNewBuyer] = useState({ name: "", telegramId: "" }); const [newWorker, setNewWorker] = useState({ label: "" }); const [catalogOpen, setCatalogOpen] = useState(false); const [selected, setSelected] = useState("buyer-demo"); const [message, setMessage] = useState(""); const [packageError, setPackageError] = useState(""); const [editingPackage, setEditingPackage] = useState<PackageDraft | null>(null);
  const [form, setForm] = useState({ workerId: "", wording: "", groups: "", intervalMinutes: "15", bases: "", division: "", keywords: "", blacklist: "", commentWording: "", mode: "APPROVAL", planBroadcast: true, planComment: true });
  const load = async () => { try { setOverview(await api("/api/admin/overview")); } catch (e) { setMessage((e as Error).message); } };
  useEffect(() => { void load(); }, []);
  const buyer = overview?.buyers.find((item) => item.id === selected); const assigned = overview?.broadcasts.find((item) => item.buyerId === selected); const lpmTargets = overview?.lpmTargets.filter((item) => item.buyerId === selected) ?? []; const comment = overview?.comments.find((item) => item.buyerId === selected);
  useEffect(() => { const firstDivision = comment?.divisions[0]; if (!buyer) return; setForm({ workerId: buyer.workerId ?? "", wording: assigned?.wording ?? "", groups: assigned?.groups.join("\n") ?? "", intervalMinutes: String(assigned?.intervalMinutes ?? 15), bases: comment?.bases.join("\n") ?? "", division: firstDivision?.name ?? "Produk", keywords: firstDivision?.keywords.join("\n") ?? "", blacklist: firstDivision?.blacklist.join("\n") ?? "", commentWording: firstDivision?.wording ?? "", mode: comment?.mode ?? "APPROVAL", planBroadcast: buyer.planBroadcast, planComment: buyer.planComment }); }, [selected, buyer?.workerId, assigned?.wording, comment?.divisions]);
  const update = (key: keyof typeof form, value: string | boolean) => setForm((old) => ({ ...old, [key]: value }));
  const addBuyer = async () => { if (!newBuyer.name.trim() || !newBuyer.telegramId.trim()) return; try { const result = await api<{ buyer: Buyer }>("/api/admin/buyers", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(newBuyer) }); setSelected(result.buyer.id); setNewBuyer({ name: "", telegramId: "" }); setAddingBuyer(false); setSettingUp(true); await load(); } catch (e) { setMessage((e as Error).message); } };
  const addWorker = async () => { if (!newWorker.label.trim()) return; try { await api("/api/admin/workers", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(newWorker) }); setNewWorker({ label: "" }); setAddingWorker(false); await load(); } catch (e) { setMessage((e as Error).message); } };
  const submit = async () => { if (!buyer) return; setMessage(""); try { await api("/api/admin/buyers/" + selected + "/setup", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...form, groups: form.groups.split("\n").filter(Boolean), divisions: [{ id: "legacy", name: form.division, keywords: form.keywords, blacklist: form.blacklist, wording: form.commentWording }] }) }); setMessage("Layanan pelanggan sudah diperbarui."); await load(); } catch (e) { setMessage((e as Error).message); } };
  const startPackage = (service: "ADMIN_BROADCAST" | "USERBOT_PROMO") => {
    const current = (overview?.packages ?? []).filter((item) => item.service === service);
    const days = [7, 14, 30, 60, 90, 180, 365]; const caps = [5, 10, 15];
    const available = days.flatMap((durationDays) => caps.map((maxGroups) => ({ durationDays, maxGroups }))).find((choice) => !current.some((item) => item.durationDays === choice.durationDays && item.maxGroups === choice.maxGroups));
    const fallback = { durationDays: current.length + 1, maxGroups: 1 };
    setPackageError(""); setEditingPackage({ service, name: "", price: "", durationDays: String((available ?? fallback).durationDays), maxGroups: String((available ?? fallback).maxGroups), enabled: false });
  };
  const updateEditingPackage = (key: "price" | "durationDays" | "maxGroups" | "enabled", value: string | boolean) => setEditingPackage((item) => item ? { ...item, [key]: key === "enabled" ? Boolean(value) : String(value) } : item);
  const savePackage = async () => { if (!editingPackage) return; setMessage(""); setPackageError(""); const price = Number(editingPackage.price); const durationDays = Number(editingPackage.durationDays); const maxGroups = Number(editingPackage.maxGroups); if (!editingPackage.price.trim() || !editingPackage.durationDays.trim() || !editingPackage.maxGroups.trim()) { setPackageError("Lengkapi harga, masa aktif, dan kapasitas LPM."); return; } try { const isExisting = Boolean(editingPackage.id); await api(isExisting ? "/api/admin/packages/" + editingPackage.id : "/api/admin/packages", { method: isExisting ? "PUT" : "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ...editingPackage, price, durationDays, maxGroups }) }); setEditingPackage(null); setMessage("Paket langganan sudah disimpan."); await load(); } catch (e) { setPackageError((e as Error).message); } };
  const removePackage = async (item: Package) => { if (!item.id || !window.confirm(`Hapus paket ${item.name}?`)) return; setMessage(""); try { await api("/api/admin/packages/" + item.id, { method: "DELETE" }); setMessage("Paket sudah dihapus."); await load(); } catch (e) { setMessage((e as Error).message); } };
  if (!overview) return <main className="shell loading">Membuka layanan…</main>;
  if (customerPage) return <CustomerPage onBack={() => { setCustomerPage(false); void load(); }} />;
  if (workerPage) return <WorkerPage onBack={() => { setWorkerPage(false); void load(); }} />;
  if (commercePage) return <CommercePage onBack={() => { setCommercePage(false); void load(); }} />;
  const activeCount = overview.buyers.filter((item) => item.planBroadcast || item.planComment).length;
  const readyWorkers = overview.workers.filter((item) => item.status === "AVAILABLE").length;
  return <main className="shell admin">
    <header><div className="eyebrow">PUSAT PROMOSI</div><h1>Panel Admin.</h1><p>Kelola layanan dari sini.</p></header>
    {message && <div className="notice">{message}</div>}
    {!panelOpen ? <><section className="service-card broadcast-card"><div className="service-top"><div><span className="icon-tile broadcast-icon"><ProductIcon name="broadcast" /></span><div><div className="label">PELANGGAN</div><h2>{activeCount} aktif</h2></div></div><Tag>{overview.buyers.length}</Tag></div><div className="signal"><b>{readyWorkers} akun siap</b></div></section>
      <section className="service-card comment-card"><div className="service-top"><div><span className="icon-tile comment-icon"><ProductIcon name="comment" /></span><div><div className="label">AKUN PROMOSI</div><h2>{overview.workers.length} akun</h2></div></div><Tag>{readyWorkers} siap</Tag></div></section>
      <button className="panel-trigger" onClick={() => setPanelOpen(true)}><span>Buka Panel</span><small>Kelola layanan</small></button></> :
      <section className="admin-panel"><div className="panel-title"><div><div className="eyebrow">PANEL ADMIN</div><h2>Kelola layanan.</h2></div><button className="close-panel" onClick={() => { setPanelOpen(false); setSettingUp(false); }}>Tutup</button></div>
        <div className="admin-snapshot"><div><span>PELANGGAN</span><b>{overview.buyers.length}</b></div><div><span>AKUN SIAP</span><b>{readyWorkers}</b></div><div><span>MASUK HARI INI</span><b>{rupiah(overview.commerce.today)}</b></div></div>
        <button className="admin-tool commerce-tool" onClick={() => setCommercePage(true)}><span className="icon-tile sales-icon"><ProductIcon name="sales" /></span><div><b>Penjualan</b><span>{overview.commerce.paidCount} pembayaran lunas</span></div><i>→</i></button>
        <button className="admin-tool" onClick={() => { setCatalogOpen(!catalogOpen); setEditingPackage(null); }}><span className="icon-tile comment-icon"><ProductIcon name="comment" /></span><div><b>Paket langganan</b></div><i>{catalogOpen ? "−" : "+"}</i></button>
        {catalogOpen && <section className="package-manager"><div className="package-manager-head"><div><div className="label">PAKET</div><h3>Langganan buyer</h3></div><Tag>{overview.packages.length}</Tag></div>
          {editingPackage && <section className="package-editor"><div className="section-title"><span>{productLabel(editingPackage.service).toUpperCase()} · {editingPackage.id ? "UBAH" : "BARU"}</span><button className="quiet-button" onClick={() => { setEditingPackage(null); setPackageError(""); }}>Batal</button></div><div className="editor-grid"><label>Nama paket<input value={editingPackage.name} onChange={(e) => setEditingPackage((item) => item ? { ...item, name: e.target.value } : item)} placeholder={productLabel(editingPackage.service)} /></label><label>Harga<input type="number" min="0" max="10000000" value={editingPackage.price} onChange={(e) => updateEditingPackage("price", e.target.value)} placeholder="25000" /></label><label>Masa aktif<input type="number" min="1" max="365" value={editingPackage.durationDays} onChange={(e) => updateEditingPackage("durationDays", e.target.value)} /></label><label>Kapasitas LPM<input type="number" min="1" value={editingPackage.maxGroups} onChange={(e) => updateEditingPackage("maxGroups", e.target.value)} /></label></div><label className="package-switch"><input type="checkbox" checked={Boolean(editingPackage.enabled)} onChange={(e) => updateEditingPackage("enabled", e.target.checked)} /> Tampilkan ke buyer</label>{packageError && <div className="package-form-error">{packageError}</div>}<button className="save" onClick={() => void savePackage()}>Simpan</button></section>}
          {(["ADMIN_BROADCAST", "USERBOT_PROMO"] as const).map((service) => { const items = overview.packages.filter((item) => item.service === service); return <section className="package-service" key={service}><div className="package-service-head"><div><span>{productLabel(service).toUpperCase()}</span><b>{service === "ADMIN_BROADCAST" ? "Akun promosi dari admin" : "Auto Jaseb akun buyer + Auto Komen MF"}</b></div><button onClick={() => startPackage(service)}>+ Paket</button></div>{items.length ? <div className="package-rows">{items.map((item) => <article className="package-row" key={item.id}><div><b>{item.name || packageLabel(item)}</b><span>{packageLabel(item)} · {rupiah(item.price)}</span></div><div className="package-row-actions"><Tag>{item.enabled ? "Tampil" : "Simpan"}</Tag><button onClick={() => { setPackageError(""); setEditingPackage({ ...item, price: String(item.price), durationDays: String(item.durationDays), maxGroups: String(item.maxGroups) }); }}>Ubah</button><button className="danger-button" onClick={() => void removePackage(item)}>Hapus</button></div></article>)}</div> : <div className="package-empty">Belum ada paket.</div>}</section>; })}
        </section>}
        <button className="admin-tool" onClick={() => setCustomerPage(true)}><span className="icon-tile broadcast-icon"><ProductIcon name="broadcast" /></span><div><b>Pelanggan</b><span>Setup layanan per pelanggan</span></div><i>→</i></button>
        <button className="admin-tool" onClick={() => setWorkerPage(true)}><span className="icon-tile comment-icon"><ProductIcon name="comment" /></span><div><b>Akun worker</b></div><i>→</i></button>
        {settingUp && <section className="setup embedded-setup"><div className="section-title"><span>PELANGGAN</span><button onClick={() => setAddingBuyer((value) => !value)}>+ Tambah</button></div>{addingBuyer && <div className="worker-add"><label>Nama pelanggan<input value={newBuyer.name} onChange={(event) => setNewBuyer((old) => ({ ...old, name: event.target.value }))} /></label><label>ID Telegram pelanggan<input value={newBuyer.telegramId} onChange={(event) => setNewBuyer((old) => ({ ...old, telegramId: event.target.value }))} /></label><button className="save" onClick={() => void addBuyer()}>Simpan</button></div>}<div className="buyer-picker">{overview.buyers.map((item) => <button className={selected === item.id ? "chosen" : ""} key={item.id} onClick={() => setSelected(item.id)}><b>{item.name}</b><span>{item.planBroadcast || item.planComment ? "siap" : "baru"}</span></button>)}</div>{buyer ? <><div className="access-pills"><label><input type="checkbox" checked={form.planBroadcast} onChange={(e) => update("planBroadcast", e.target.checked)} /> Auto Sebar</label><label><input type="checkbox" checked={form.planComment} onChange={(e) => update("planComment", e.target.checked)} /> Auto Komen</label></div>{form.planBroadcast && <fieldset><legend>AUTO SEBAR</legend><label>Akun kerja<select value={form.workerId} onChange={(e) => update("workerId", e.target.value)}><option value="">Pilih akun</option>{overview.workers.filter((item) => !item.buyerId || item.buyerId === selected).map((item) => <option key={item.id} value={item.id}>{item.label} · @{item.username}</option>)}</select></label><label>Wording<textarea value={form.wording} onChange={(e) => update("wording", e.target.value)} placeholder="Tulis wording…" /></label><label>Grup LPM<textarea value={form.groups} onChange={(e) => update("groups", e.target.value)} placeholder="Satu grup per baris" /></label>{lpmTargets.length ? <div className="lpm-target-list">{lpmTargets.map((target) => <div className={`lpm-target ${target.status.toLowerCase()}`} key={target.id}><b>@{target.username}</b><span>{lpmStatus(target.status)}</span></div>)}</div> : null}<label>Jeda (menit)<input value={form.intervalMinutes} inputMode="numeric" onChange={(e) => update("intervalMinutes", e.target.value)} /></label></fieldset>}{form.planComment && <fieldset><legend>AUTO KOMEN MF</legend><label>Base<textarea value={form.bases} onChange={(e) => update("bases", e.target.value)} placeholder="Satu base per baris" /></label><label>Divisi<input value={form.division} onChange={(e) => update("division", e.target.value)} /></label><label>Keyword<textarea value={form.keywords} onChange={(e) => update("keywords", e.target.value)} /></label><label>Blacklist OOT<textarea value={form.blacklist} onChange={(e) => update("blacklist", e.target.value)} /></label><label>Wording<textarea value={form.commentWording} onChange={(e) => update("commentWording", e.target.value)} /></label><label>Metode<select value={form.mode} onChange={(e) => update("mode", e.target.value)}><option value="APPROVAL">Approval</option><option value="AUTO">Otomatis</option></select></label></fieldset>}<button className="save" onClick={() => void submit()}>Simpan</button></> : <div className="empty">Tambah pelanggan dulu.</div>}<div className="section-title"><span>AKUN WORKER</span><button onClick={() => setAddingWorker((value) => !value)}>+ Tambah</button></div>{addingWorker && <div className="worker-add"><label>Nama akun<input value={newWorker.label} onChange={(event) => setNewWorker({ label: event.target.value })} /></label><button className="save" onClick={() => void addWorker()}>Simpan</button></div>}</section>}
      </section>}
  </main>;
}

function App() {
  const [role, setRole] = useState<"ADMIN" | "BUYER" | null>(null); const [error, setError] = useState("");
  useEffect(() => { void api<{ role: "ADMIN" | "BUYER" }>("/api/app/session").then((session) => setRole(session.role)).catch((e) => setError((e as Error).message)); }, []);
  if (error) return <main className="shell loading"><div className="notice error">{error}</div></main>;
  if (!role) return <main className="shell loading">Membuka layanan…</main>;
  return role === "ADMIN" ? <AdminApp /> : <BuyerApp />;
}

createRoot(document.getElementById("root")!).render(<App />);
